CREATE TABLE users (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('student','headman','teacher','coordinator')));
CREATE TABLE groups (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text UNIQUE NOT NULL);
CREATE TABLE memberships (user_id integer REFERENCES users, group_id integer REFERENCES groups, starts_on date NOT NULL, ends_on date, PRIMARY KEY(user_id,group_id,starts_on), CHECK(ends_on IS NULL OR ends_on >= starts_on));
CREATE TABLE courses (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, title text NOT NULL UNIQUE);
CREATE TABLE offerings (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, course_id integer NOT NULL REFERENCES courses, teacher_id integer NOT NULL REFERENCES users, group_id integer NOT NULL REFERENCES groups, semester text NOT NULL);
CREATE TABLE sessions (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, offering_id integer NOT NULL REFERENCES offerings, title text NOT NULL, starts_at timestamptz NOT NULL, room text, cancelled boolean NOT NULL DEFAULT false);
CREATE TABLE homework (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, session_id integer NOT NULL REFERENCES sessions, title text NOT NULL, description text NOT NULL DEFAULT '', due_at timestamptz NOT NULL);
CREATE TABLE homework_done (homework_id integer REFERENCES homework, user_id integer REFERENCES users, PRIMARY KEY(homework_id,user_id));
CREATE TABLE attendance (session_id integer REFERENCES sessions, student_id integer REFERENCES users, status text NOT NULL CHECK(status IN ('present','absent','late','excused')), updated_by integer NOT NULL REFERENCES users, updated_at timestamptz NOT NULL DEFAULT now(), reason text, PRIMARY KEY(session_id,student_id));
CREATE TABLE attendance_history (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, session_id integer NOT NULL, student_id integer NOT NULL, status text NOT NULL, changed_by integer NOT NULL REFERENCES users, reason text, changed_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION log_attendance() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO attendance_history(session_id, student_id, status, changed_by, reason) VALUES(NEW.session_id, NEW.student_id, NEW.status, NEW.updated_by, NEW.reason); RETURN NEW; END $$;
CREATE TRIGGER attendance_audit AFTER INSERT OR UPDATE ON attendance FOR EACH ROW EXECUTE FUNCTION log_attendance();
CREATE TABLE debts (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, student_id integer NOT NULL REFERENCES users, offering_id integer NOT NULL REFERENCES offerings, reason text NOT NULL, source text NOT NULL, created_by integer NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), closed boolean NOT NULL DEFAULT false);
CREATE TABLE retakes (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, offering_id integer NOT NULL REFERENCES offerings, starts_at timestamptz NOT NULL, room text NOT NULL, capacity integer NOT NULL CHECK(capacity > 0));
CREATE TABLE retake_registrations (retake_id integer REFERENCES retakes, debt_id integer REFERENCES debts, result text CHECK(result IN ('passed','failed')), PRIMARY KEY(retake_id,debt_id));
CREATE TABLE materials (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, offering_id integer NOT NULL REFERENCES offerings, title text NOT NULL, url text NOT NULL, version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE contacts (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL, position text NOT NULL, email text NOT NULL, verified_at date NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE projects (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, owner_id integer NOT NULL REFERENCES users, title text NOT NULL, description text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE project_roles (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, project_id integer NOT NULL REFERENCES projects, title text NOT NULL, skills text NOT NULL DEFAULT '', capacity integer NOT NULL CHECK(capacity > 0));
CREATE TABLE applications (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, role_id integer NOT NULL REFERENCES project_roles, user_id integer NOT NULL REFERENCES users, message text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')), UNIQUE(role_id,user_id));
CREATE TABLE project_members (project_id integer REFERENCES projects, user_id integer REFERENCES users, role_id integer NOT NULL REFERENCES project_roles, PRIMARY KEY(project_id,user_id));
CREATE TABLE login_sessions (token_hash text PRIMARY KEY, user_id integer NOT NULL REFERENCES users, expires_at timestamptz NOT NULL);
